        IntegrityMode integrityMode = integrityMode(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        configuredIntegrityMode = integrityMode;
        configureFileNameStrategy(properties);
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s=true", ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        try {
            storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).getCanonicalFile();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        StoreState state = getStoreState(storeFolder);
        synchronized (state.lock) {
            prepareStoreFolder(state);
            boolean indexExists = hasFileSystemEntry(state.indexFile);
            if (indexExists && !isRegularFileWithoutFollowingLinks(state.indexFile)) {
                throw new StoreInitializationFailedException(String.format(
                        "The store index %s is not a regular file directly in the store folder", state.indexFile));
            }
            if (!indexExists && !storeCreationAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }

            Properties propertiesFromIndex = indexExists ? loadProperties(state.indexFile) : new Properties();
            IntegrityReport report = integrityMode == IntegrityMode.IGNORE
                    ? IntegrityReport.empty()
                    : inspect(state, propertiesFromIndex);
            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
                throw new StoreInitializationFailedException(report.asMessage());
            }
            if (integrityMode == IntegrityMode.REPAIR) {
                repair(state, propertiesFromIndex, report);
            }
            if (!indexExists) {
                try {
                    writeProperties(state.indexFile, propertiesFromIndex);
                } catch (IOException e) {
                    throw new StoreInitializationFailedException(e);
                }
            }
            state.properties = propertiesFromIndex;
            storedRules = state;
        }
        log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRules.indexFile.getAbsolutePath());
    }

    private void configureFileNameStrategy(Properties properties) {
        if (strategyWasGivenToConstructor) {
            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot configure %s when a RuleViolationFileNameStrategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            ruleViolationFileNameStrategy = constructorStrategy;
            fileNameMode = FileNameMode.CUSTOM;
            return;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
        if ("random".equals(configured)) {
            ruleViolationFileNameStrategy = description -> UUID.randomUUID().toString();
            fileNameMode = FileNameMode.RANDOM;
        } else if ("description".equals(configured)) {
            ruleViolationFileNameStrategy = TextFileBasedViolationStore::descriptionFileName;
            fileNameMode = FileNameMode.DESCRIPTION;
        } else {
            ruleViolationFileNameStrategy = instantiateStrategy(configured);
            fileNameMode = FileNameMode.CUSTOM;
        }
    }

    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
        try {
            Class<?> strategyClass = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
            }
            return (RuleViolationFileNameStrategy) strategyClass.getConstructor().newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate RuleViolationFileNameStrategy configured by %s=%s; it must have a public no-argument constructor",
                    FILE_NAMES_PROPERTY_NAME, className), e);
        }
    }

    private IntegrityMode integrityMode(String configured) {
        for (IntegrityMode mode : IntegrityMode.values()) {
            if (mode.value.equals(configured)) {
                return mode;
            }
        }
        throw new StoreInitializationFailedException(String.format(
                "Invalid value '%s' for %s; accepted values are repair, fail and ignore",
                configured, INTEGRITY_PROPERTY_NAME));
    }

    private static StoreState getStoreState(File folder) {
        String path = folder.getPath();
        return STORES_BY_PATH.computeIfAbsent(path, ignored -> new StoreState(folder));
    }

    private void prepareStoreFolder(StoreState state) {
        if (hasFileSystemEntry(state.folder) && !Files.isDirectory(state.folder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
            throw new StoreInitializationFailedException(String.format("Store path %s is not a directory", state.folder));
        }
        if (!Files.isDirectory(state.folder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
            if (!storeCreationAllowed || (!state.folder.mkdirs() && !state.folder.isDirectory())) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }
        }
    }

    private static Properties loadProperties(File file) {
        Properties result = new Properties();
        try (InputStream inputStream = Files.newInputStream(file.toPath())) {
            result.load(inputStream);
            return result;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        StoreState state = requireInitialized();
        synchronized (state.lock) {
            state.reload();
            return state.properties.containsKey(normalized(rule.getDescription()));
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        StoreState state = requireInitialized();
        synchronized (state.lock) {
            state.reloadForUpdate();
            String description = normalized(rule.getDescription());
            String existingFileName = state.properties.getProperty(description);
            if (violations.isEmpty() && configuredIntegrityMode == IntegrityMode.REPAIR) {
                if (existingFileName != null) {
                    forgetRule(state, description, existingFileName);
                }
                return;
            }

            String fileName = existingFileName == null ? requiredFileName(rule.getDescription()) : existingFileName;
            File target = validateWriteTarget(state, description, fileName, existingFileName != null);
            byte[] oldContents = existingRegularFile(target) ? readBytes(target) : null;
            byte[] newContents = serializedViolations(violations);
            writeContentsAtomically(target, newContents);
            if (existingFileName == null) {
                Properties updated = copyOf(state.properties);
                updated.setProperty(description, normalized(fileName));
                try {
                    writeProperties(state.indexFile, updated);
                    state.properties = updated;
                } catch (IOException e) {
                    restoreContents(target, oldContents);
                    throw new StoreUpdateFailedException(e);
                }
            }
        }
    }

    private void forgetRule(StoreState state, String description, String fileName) {
        boolean shared = isSharedByAnotherEntry(state, description, fileName);
        byte[] oldContents = null;
        File target = null;
        if (!shared) {
            File named = new File(state.folder, fileName);
            if (hasFileSystemEntry(named) && !isSafeExistingFile(state, fileName)) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot remove rule '%s': its stored file is not a regular file directly in the store folder", description));
            }
            target = canonicalFile(state.folder, fileName);
            if (hasFileSystemEntry(named)) {
                oldContents = readBytes(target);
                try {
                    deleteNamedFile(state, fileName);
                } catch (IOException e) {
                    throw new StoreUpdateFailedException(e);
                }
            }
        }
        Properties updated = copyOf(state.properties);
        updated.remove(description);
        try {
            writeProperties(state.indexFile, updated);
            state.properties = updated;
        } catch (IOException e) {
            if (!shared && target != null && oldContents != null) {
                restoreContents(target, oldContents);
            }
            throw new StoreUpdateFailedException(e);
        }
    }

    private String requiredFileName(String description) {
        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
        if (result == null || result.trim().isEmpty()) {
            throw new StoreUpdateFailedException(String.format(
                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
        }
        return normalized(result);
    }

    private File validateWriteTarget(StoreState state, String description, String fileName, boolean knownRule) {
        if (fileName == null || fileName.trim().isEmpty()) {
            throw new StoreUpdateFailedException(String.format("Rule '%s' has no stored file name", description));
        }
        File target;
        try {
            target = canonicalFile(state.folder, fileName);
        } catch (RuntimeException e) {
            throw new StoreUpdateFailedException(e);
        }
        if (!target.getParentFile().equals(state.folder) || target.equals(state.indexFile)) {
            throw new StoreUpdateFailedException(String.format(
                    "Refusing to write rule '%s' outside the store folder or over %s", description, STORED_RULES_FILE_NAME));
        }
        if (hasFileSystemEntry(new File(state.folder, fileName)) && !existingRegularFile(target)) {
            throw new StoreUpdateFailedException(String.format("Stored file %s is not a regular file", fileName));
        }
        if (!knownRule && hasFileSystemEntry(target)) {
            throw new StoreUpdateFailedException(String.format("Stored file %s is already occupied", fileName));
        }
        if (!knownRule) {
            for (String otherDescription : state.properties.stringPropertyNames()) {
                String otherFileName = state.properties.getProperty(otherDescription);
                if (fileName.equals(otherFileName) || sameResolvedFile(state.folder, fileName, otherFileName)) {
                    throw new StoreUpdateFailedException(String.format(
                            "Stored file %s is recorded by another rule", fileName));
                }
            }
        }
        return target;
    }

    private boolean isSafeExistingFile(StoreState state, String fileName) {
        try {
            File target = canonicalFile(state.folder, fileName);
            return target.getParentFile().equals(state.folder)
                    && !target.equals(state.indexFile)
                    && (!hasFileSystemEntry(new File(state.folder, fileName)) || existingRegularFile(target));
        } catch (RuntimeException e) {
            return false;
        }
    }

    private boolean isSharedByAnotherEntry(StoreState state, String description, String fileName) {
        for (String otherDescription : state.properties.stringPropertyNames()) {
            if (!description.equals(otherDescription)) {
                String otherFileName = state.properties.getProperty(otherDescription);
                if (fileName.equals(otherFileName) || sameResolvedFile(state.folder, fileName, otherFileName)) {
                    return true;
                }
            }
        }
        return false;
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        StoreState state = requireInitialized();
        synchronized (state.lock) {
            state.reload();
            String fileName = state.properties.getProperty(normalized(rule.getDescription()));
            checkArgument(fileName != null, "No rule stored with description '%s'", rule.getDescription());
            List<String> result = readLines(new File(state.folder, fileName));
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private StoreState requireInitialized() {
        if (storedRules == null) {
            throw new IllegalStateException("Violation store has not been initialized");
        }
        return storedRules;
    }

    private static byte[] serializedViolations(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        }
        return builder.toString().getBytes(UTF_8);
    }

    private static String escape(String violation) {
        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
    }

    private static String unescape(String violation) {
        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
    }

    private static List<String> readLines(File file) {
        String violationsText;
        try {
            violationsText = new String(Files.readAllBytes(file.toPath()), UTF_8);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
        if (isOnlyLineBreaks(violationsText)) {
            return Collections.emptyList();
        }
        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
                .filter(line -> !isOnlyLineBreaks(line))
                .map(TextFileBasedViolationStore::unescape)
                .collect(toList());
    }

    private static boolean isOnlyLineBreaks(String text) {
        if (text.isEmpty()) {
            return true;
        }
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) != '\n' && text.charAt(i) != '\r') {
                return false;
            }
        }
        return true;
    }

    private IntegrityReport inspect(StoreState state, Properties properties) {
        List<Entry> entries = new ArrayList<>();
        for (String description : properties.stringPropertyNames()) {
            entries.add(new Entry(description, properties.getProperty(description)));
        }
        entries.sort(Comparator.comparing(entry -> entry.description));

        Map<String, Integer> names = counts(entries, entry -> entry.fileName);
        Map<String, Integer> resolvedNames = new HashMap<>();
        for (Entry entry : entries) {
            entry.canonicalPath = canonicalPath(state.folder, entry.fileName);
            if (Files.isRegularFile(canonicalFile(state.folder, entry.fileName).toPath())) {
                resolvedNames.put(entry.canonicalPath, resolvedNames.getOrDefault(entry.canonicalPath, 0) + 1);
            }
            if (fileNameMode != FileNameMode.RANDOM) {
                entry.derivedFileName = requiredInitializationFileName(entry.description);
            }
        }
        Map<String, Integer> derivedNames = counts(entries, entry -> entry.derivedFileName);
        for (Entry entry : entries) {
            entry.shared = names.getOrDefault(entry.fileName, 0) > 1
                    || resolvedNames.getOrDefault(entry.canonicalPath, 0) > 1;
            File resolved = canonicalFile(state.folder, entry.fileName);
            entry.broken = resolved.equals(state.indexFile)
                    || !resolved.getParentFile().equals(state.folder)
                    || !Files.isRegularFile(resolved.toPath())
                    || !canRead(resolved);
            if (!entry.broken) {
                try {
                    entry.resolved = readLines(resolved).isEmpty();
                } catch (RuntimeException e) {
                    entry.broken = true;
                }
            }
            entry.misplaced = entry.derivedFileName != null && !entry.fileName.equals(entry.derivedFileName);
            if (entry.misplaced) {
                entry.occupied = derivedPathIsOccupied(state, properties, entry, entries);
            }
            entry.colliding = entry.derivedFileName != null
                    && derivedNames.getOrDefault(entry.derivedFileName, 0) > 1;
        }
        List<String> unowned = directUnownedFiles(state, entries);
        return new IntegrityReport(entries, unowned);
    }

    private String requiredInitializationFileName(String description) {
        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
        if (result == null || result.trim().isEmpty()) {
            throw new StoreInitializationFailedException(String.format(
                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
        }
        return normalized(result);
    }

    private static Map<String, Integer> counts(List<Entry> entries, EntryValue value) {
        Map<String, Integer> result = new HashMap<>();
        for (Entry entry : entries) {
            String item = value.get(entry);
            if (item != null) {
                result.put(item, result.getOrDefault(item, 0) + 1);
            }
        }
        return result;
    }

    private boolean derivedPathIsOccupied(StoreState state, Properties properties, Entry entry, List<Entry> entries) {
        File derived;
        try {
            derived = canonicalFile(state.folder, entry.derivedFileName);
        } catch (RuntimeException e) {
            return true;
        }
        if (!derived.getParentFile().equals(state.folder) || derived.equals(state.indexFile)) {
            return true;
        }
        if (hasFileSystemEntry(new File(state.folder, entry.derivedFileName))) {
            return true;
        }
        for (Entry other : entries) {
            if (other != entry && (entry.derivedFileName.equals(other.fileName)
                    || sameResolvedFile(state.folder, entry.derivedFileName, other.fileName))) {
                return true;
            }
        }
        return false;
    }

    private static List<String> directUnownedFiles(StoreState state, List<Entry> entries) {
        Set<String> ownedNames = new HashSet<>();
        Set<String> ownedPaths = new HashSet<>();
        for (Entry entry : entries) {
            ownedNames.add(entry.fileName);
            ownedPaths.add(entry.canonicalPath);
        }
        File[] files = state.folder.listFiles();
        if (files == null) {
            return Collections.emptyList();
        }
        List<String> result = new ArrayList<>();
        for (File file : files) {
            if (!file.getName().equals(STORED_RULES_FILE_NAME)
                    && !ownedNames.contains(file.getName())
                    && !ownedPaths.contains(canonicalPath(state.folder, file.getName()))
                    && isRegularFileWithoutFollowingLinks(file)) {
                result.add(file.getName());
            }
        }
        Collections.sort(result);
        return result;
    }

    private void repair(StoreState state, Properties properties, IntegrityReport report) {
        boolean changed = false;
        for (Entry entry : report.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                properties.remove(entry.description);
                changed = true;
            } else if (entry.resolved) {
                try {
                    deleteNamedFile(state, entry.fileName);
                } catch (IOException e) {
                    throw new StoreInitializationFailedException(e);
                }
                properties.remove(entry.description);
                changed = true;
            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
                try {
                    moveNamedFile(state, entry.fileName, entry.derivedFileName);
                } catch (IOException e) {
                    throw new StoreInitializationFailedException(e);
                }
                properties.setProperty(entry.description, normalized(entry.derivedFileName));
                changed = true;
            }
        }
        if (changed) {
            try {
                writeProperties(state.indexFile, properties);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
        }
    }

    private static void deleteNamedFile(StoreState state, String fileName) throws IOException {
        File named = new File(state.folder, fileName);
        File target = canonicalFile(state.folder, fileName);
        boolean namedIsLink = Files.isSymbolicLink(named.toPath());
        if (target.equals(state.indexFile) || !target.getParentFile().equals(state.folder)) {
            throw new IOException("Refusing to delete a file outside the store folder");
        }
        if (!Files.isRegularFile(target.toPath())) {
            throw new IOException("Stored file is not regular");
        }
        Files.delete(target.toPath());
        if (namedIsLink && hasFileSystemEntry(named)) {
            Files.delete(named.toPath());
        }
    }

    private static void moveNamedFile(StoreState state, String oldName, String newName) throws IOException {
        File sourceNamed = new File(state.folder, oldName);
        File source = canonicalFile(state.folder, oldName);
        boolean sourceIsLink = Files.isSymbolicLink(sourceNamed.toPath());
        File target = canonicalFile(state.folder, newName);
        if (!source.getParentFile().equals(state.folder) || !target.getParentFile().equals(state.folder)
                || target.equals(state.indexFile) || hasFileSystemEntry(new File(state.folder, newName))) {
            throw new IOException("Stored file move is not safe");
        }
        Files.move(source.toPath(), target.toPath());
        if (sourceIsLink && hasFileSystemEntry(sourceNamed)) {
            Files.delete(sourceNamed.toPath());
        }
    }

    private static boolean canRead(File file) {
        try {
            Files.readAttributes(file.toPath(), java.nio.file.attribute.BasicFileAttributes.class);
            return true;
        } catch (IOException e) {
            return false;
