    }

    private static boolean hasFileSystemEntry(File file) {
        return Files.exists(file.toPath(), LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(file.toPath());
    }

    private static boolean isRegularFileWithoutFollowingLinks(File file) {
        return Files.isRegularFile(file.toPath(), LinkOption.NOFOLLOW_LINKS);
