    private static boolean sameCanonicalFile(File folder, String first, String second) {
        return canonicalPath(folder, first).equals(canonicalPath(folder, second));
    }

    private static boolean sameResolvedFile(File folder, String first, String second) {
        return sameCanonicalFile(folder, first, second)
                && Files.isRegularFile(canonicalFile(folder, first).toPath());
    }

    private static byte[] readBytes(File file) {
        try {
