            deleteQuietly(temporary);
            throw new StoreUpdateFailedException(e);
        }
    }

    private static void restoreContents(File target, byte[] oldContents) {
        if (oldContents == null) {
            deleteQuietly(target);
        } else {
            writeContentsAtomically(target, oldContents);
        }
    }

